// A Valdi module's ClientSQL databases (sql/<Database>/*.sq) as TypeScript, generated by Valdi's own generator
// (vendor/clientsql, Python) into <generated dir>/src/sqlgen, as the Valdi compiler does: <Database>.ts and per .sq file
// <File>Queries.ts, <File>Types.ts. Files are written only when they change, and stale ones removed, so the TypeScript
// program and rolldown see a change only then.
//
// The generator requires its SQLite 3.16.0 validator (every query must compile on that SQLite):
// $VALDI_SQLITE_VALIDATOR, or the newest Bazel build of it in valdi/bazel-out. `python3`, or $PYTHON.
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import type { ValdiModule } from './valdiTs';

const generator = path.join(import.meta.dirname, 'vendor/clientsql/clientsql_main.py');

export function sqliteValidator(valdi: string): string {
  if (process.env.VALDI_SQLITE_VALIDATOR) return process.env.VALDI_SQLITE_VALIDATOR;
  const out = path.join(valdi, 'bazel-out');
  const found = (existsSync(out) ? readdirSync(out) : [])
    .flatMap(config => ['valdi+', 'valdi~'].map(repo => path.join(out, config, 'bin/external', repo, 'compiler/clientsql/sqlite_316_validator')))
    .filter(file => existsSync(file))
    .sort((a, b) => statSync(b).mtimeMs - statSync(a).mtimeMs);
  if (!found.length) {
    throw new Error('No sqlite_316_validator: run `bazel build @valdi//compiler/clientsql:sqlite_316_validator` in valdi/');
  }
  return found[0];
}

/** Generates the module's databases into `dir`/src/sqlgen; returns the files that changed (added, edited, removed). */
export function generateSqlgen(module: ValdiModule, dir: string, validator: string): string[] {
  const sqlDir = path.join(module.dir, 'sql');
  const target = path.join(dir, 'src/sqlgen');
  const databases = existsSync(sqlDir)
    ? readdirSync(sqlDir).filter(name => statSync(path.join(sqlDir, name)).isDirectory())
    : [];
  const generated = new Map<string, string>();
  const scratch = mkdtempSync(path.join(tmpdir(), 'valdi-sqlgen-'));
  try {
    for (const database of databases) {
      const out = path.join(scratch, database, module.name, 'src/sqlgen');
      // -p/-c are the database (its directory under sql/), -m the module, as the Valdi compiler passes them.
      const args = ['-s', sqlDir, '-p', database, '-c', database, '-m', module.name, '-o', out, '-l', 'typescript'];
      try {
        // -E -s: no PYTHON* environment, no user site packages; but the script's directory stays importable (unlike -I).
        execFileSync(process.env.PYTHON ?? 'python3', ['-E', '-s', generator, '--sqlite-validator', validator, ...args], {
          stdio: ['ignore', 'ignore', 'pipe'],
        });
      } catch (error) {
        const stderr = (error as { stderr?: Buffer }).stderr?.toString().trim();
        throw new Error(`${module.name}/sql/${database}: ${stderr || (error as Error).message}`);
      }
      for (const file of readdirSync(out)) generated.set(file, readFileSync(path.join(out, file), 'utf8'));
    }
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }

  const changed: string[] = [];
  const existing = existsSync(target) ? readdirSync(target) : [];
  for (const file of existing) {
    if (generated.has(file)) continue;
    rmSync(path.join(target, file));
    changed.push(path.join(target, file));
  }
  if (generated.size) mkdirSync(target, { recursive: true });
  for (const [file, content] of generated) {
    const output = path.join(target, file);
    if (existsSync(output) && readFileSync(output, 'utf8') === content) continue;
    writeFileSync(output, content);
    changed.push(output);
  }
  return changed;
}
